CREATE TABLE pilot_acceptance_events(id uuid PRIMARY KEY,sequence bigint GENERATED ALWAYS AS IDENTITY UNIQUE,branch_id uuid NOT NULL REFERENCES branches,check_key text NOT NULL CHECK(check_key IN ('PROFILE_POLICY','CATALOG_UNITS','OPENING_STOCK','STAFF_PERMISSIONS','COUNTER_TRAINING','PRINTER_SCANNER','OFF_DEVICE_RECOVERY','DEPLOYMENT_SECURITY')),status text NOT NULL CHECK(status IN ('PENDING','ATTESTED','DEFERRED')),evidence text NOT NULL CHECK(length(evidence) BETWEEN 10 AND 2000),actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pilot_acceptance_branch_check ON pilot_acceptance_events(branch_id,check_key,sequence DESC);
CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON pilot_acceptance_events FOR EACH ROW EXECUTE FUNCTION deny_history_change();
